TIMING_MARK_MIN_COLS = 5
TIMING_ROUND_MIN_COLS = 8
TIMING_ROUND_SKILL_COL = 3
TIMING_ROUND_ROUND_NUM_COL = 5
TIMING_ROUND_END_COL = 7
